import sys
import xml.etree.ElementTree as ET
import subprocess

def main():
    if len(sys.argv) != 2:
        print("config failed: Invalid number of arguments", file=sys.stderr)
        sys.exit(1)

    xml_file = sys.argv[1]

    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"config failed: {e}", file=sys.stderr)
        sys.exit(1)
    except FileNotFoundError:
        print("config failed: File not found", file=sys.stderr)
        sys.exit(1)

    if root.tag != 'job':
        print("config failed: Root element is not <job>", file=sys.stderr)
        sys.exit(1)

    command = root.attrib.get('command')
    logfile = root.attrib.get('logfile')

    if command is None or logfile is None:
        print("config failed: Missing command or logfile attribute", file=sys.stderr)
        sys.exit(1)

    try:
        with open(logfile, 'w') as log:
            process = subprocess.Popen(command, shell=True, stdout=log, stderr=subprocess.PIPE)
            _, stderr = process.communicate()
            if stderr:
                print(stderr.decode(), file=sys.stderr)
            print(f"job exited with code {process.returncode}", file=sys.stderr)
            if process.returncode != 0:
                sys.exit(1)
    except Exception as e:
        print(f"job failed: {e}", file=sys.stderr)
        sys.exit(1)

    sys.exit(0)

if __name__ == '__main__':
    main()
